/// Binary search over [`BLOCK_COLORS`] by block path.
pub fn lookup(path: &str) -> Option<(u32, u32, u8, u8)> {
    BLOCK_COLORS
        .binary_search_by(|e| e.0.cmp(path))
        .ok()
        .map(|i| {
            (BLOCK_COLORS[i].1, BLOCK_COLORS[i].2, BLOCK_COLORS[i].3, BLOCK_COLORS[i].4)
        })
}

