/// Biome tint lookup with the vanilla plains fallback.
pub fn biome(name: &str) -> (u32, u32, u32) {
    match BIOMES.binary_search_by(|e| e.0.cmp(name)) {
        Ok(i) => (BIOMES[i].1, BIOMES[i].2, BIOMES[i].3),
        Err(_) => (0x91BD59, 0x48B518, 0x3F76E4),
    }
}
